// Validate, then let at most one message per host + key through each hour.
const b = ($input.first().json.body) || {};
const str = v => typeof v === 'string' && v.trim().length > 0;
if (b.source !== 'snifrig' || !str(b.host) || !str(b.key) || !str(b.msg)) return [{ json: { route: 2 } }];
const s = $getWorkflowStaticData('global');
s.seen = s.seen || {};
const now = Date.now(), HOUR = 3600 * 1000;
for (const k of Object.keys(s.seen)) if (now - s.seen[k].at > 6 * HOUR) delete s.seen[k];
const id = (b.host + '|' + b.key).slice(0, 200);
const e = s.seen[id];
if (e && now - e.at < HOUR) { e.extra = (e.extra || 0) + 1; return [{ json: { route: 1 } }]; }
const extra = e ? (e.extra || 0) : 0;
const recent = e && now - e.at < 2 * HOUR;
s.seen[id] = { at: now, extra: 0 };
const clip = (v, n) => String(v).slice(0, n);
let text = 'snifrig on ' + clip(b.host, 60) + '\n' + clip(b.msg, 900);
if (extra > 0) text += recent ? '\n(x' + (extra + 1) + ' in the last hour)' : '\n(repeated ' + extra + ' more times earlier)';
return [{ json: { route: 0, text } }];
